<?php declare(strict_types=1); $e=static fn(mixed $v): string => htmlspecialchars((string)$v, ENT_QUOTES, "UTF-8"); ?><style>.cr-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.cr-stat{padding:22px;border-radius:14px}.cr-stat .n{font-size:30px;font-weight:700}.cr-muted{color:#667085}.cr-actions{display:flex;gap:8px;flex-wrap:wrap}.cr-badge{display:inline-block;padding:5px 9px;border-radius:999px;font-size:12px;background:#eef2f6}@media(max-width:900px){.cr-grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr!important}}</style><div class="page-header"><div><h1>Rental Requests</h1><p>Managed marketplace requests awaiting provider contact, quote or confirmation.</p></div><div class="page-actions"><a class="btn btn-primary" href="<?= config('app.base_path') ?>/commercial-rentals/requests/create">Create Request</a></div></div><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Request</th><th>Customer</th><th>Pickup / Work Location</th><th>Provider / Asset</th><th>Status</th><th>Amount</th><th>Actions</th></tr></thead><tbody><?php if(empty($requests)): ?><tr><td colspan="7"><div class="empty-state">No rental requests found.</div></td></tr><?php else: foreach($requests as $row): ?><tr><td><strong><?= $e($row['request_no']) ?></strong><br><span class="cr-muted"><?= $e($row['created_at'] ?? '') ?></span></td><td><?= $e($row['customer_name']) ?><br><?= $e($row['customer_phone']) ?></td><td><?= $e($row['pickup_address']) ?></td><td><?= $e($row['provider_name'] ?? 'Not assigned') ?><br><?= $e($row['vehicle_name'] ?? 'Not assigned') ?></td><td><span class="cr-badge"><?= $e($row['status']) ?></span></td><td><?php if($row['final_amount']!==null): ?>₹<?= number_format((float)$row['final_amount'],2) ?><?php elseif($row['quoted_amount']!==null): ?>Quote ₹<?= number_format((float)$row['quoted_amount'],2) ?><?php else: ?>—<?php endif; ?></td><td><a class="link-button" href="<?= config('app.base_path') ?>/commercial-rentals/requests/<?= (int)$row['id'] ?>">View</a> <a class="link-button" href="<?= config('app.base_path') ?>/commercial-rentals/requests/<?= (int)$row['id'] ?>/edit">Edit</a></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
